'use strict';

/* Exact Coach Desk / Coach Field route bodies for the everyday Coach pages. */
(function () {
  var page = document.body && document.body.getAttribute('data-coach-page');
  if (!page) return;
  var desk = document.getElementById('coachDeskPage');
  var field = document.getElementById('coachFieldPage');
  var state = {};

  function esc(v){return window.CoachV2 ? window.CoachV2.esc(v) : String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function clean(h){return window.CoachV2 ? window.CoachV2.clean(h) : h;}
  function api(method,path,body){return window.api(method,path,body);}
  function list(r,keys){if(Array.isArray(r))return r;for(var i=0;i<keys.length;i++)if(r&&Array.isArray(r[keys[i]]))return r[keys[i]];return[];}
  function value(o,keys){for(var i=0;i<keys.length;i++)if(o&&o[keys[i]]!=null&&o[keys[i]]!=='')return o[keys[i]];return null;}
  function nameOf(p){return [p&&p.first_name,p&&p.last_name].filter(Boolean).join(' ').trim()||value(p,['name','player_name'])||'Player';}
  function initials(v){return window.CoachV2?window.CoachV2.initials(v):String(v||'PL').slice(0,2).toUpperCase();}
  function team(){return window.CoachV2?window.CoachV2.teamName():'Your team';}
  function age(){return window.CoachV2?window.CoachV2.ageGroup():'';}
  function user(){return window.Auth&&window.Auth.user?window.Auth.user:{};}
  function fullName(){return window.CoachV2?window.CoachV2.fullName():'Coach';}
  function firstName(){return window.CoachV2?window.CoachV2.firstName():'Coach';}
  function num(v,fallback){var n=Number(v);return Number.isFinite(n)?n:(fallback==null?0:fallback);}
  function formatDate(raw,withTime){if(!raw)return 'Date to be confirmed';var d=new Date(String(raw).length<=10?String(raw)+'T12:00:00':raw);if(Number.isNaN(d.getTime()))return String(raw);var s=d.toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'});if(withTime&&typeof withTime==='string')s+=' · '+withTime.slice(0,5);return s;}
  function fmtMoney(v){var n=Number(v);if(!Number.isFinite(n)||n<=0)return 'Developing';if(n>=1000000)return '£'+(n/1000000).toFixed(1)+'m';if(n>=1000)return '£'+Math.round(n/1000)+'k';return '£'+Math.round(n);}
  function routeMessage(message,error){return '<div class="coach-route-message'+(error?' error':'')+'">'+esc(message)+'</div>';}
  function positionGroup(p){var s=String(value(p,['specific_position','primary_position','position','position_group'])||'').toUpperCase();if(/GK|GOAL/.test(s))return'GK';if(/CB|LB|RB|WB|DEF/.test(s))return'DEF';if(/CM|DM|AM|MID/.test(s))return'MID';return'ATT';}
  function position(p){return value(p,['specific_position','primary_position','position','position_group'])||'—';}
  function completion(p){
    var explicit=Number(value(p,['profile_completion','profileCompletion','completion_percent','evidence_completion']));
    if(Number.isFinite(explicit))return Math.max(0,Math.min(100,Math.round(explicit<=1?explicit*100:explicit)));
    var checks=[nameOf(p)!=='Player',!!value(p,['age_group','ageGroup']),!!position(p),Number.isFinite(Number(value(p,['overall_rating','overallRating','overall']))),!!value(p,['preferred_foot','foot']),!!value(p,['height_category','heightCategory','height']),!!value(p,['build_category','buildCategory','weight']),num(value(p,['appearances','apps']),0)>0];
    return Math.round(checks.filter(Boolean).length/checks.length*100);
  }
  function evidenceClass(pc){return pc<45?'low':pc<70?'mid':'';}
  function tagForPlayer(p,pc){
    var scout=Boolean(value(p,['scout_interest','has_scout_interest','scoutInterest']));
    var videos=num(value(p,['approved_video_count','approvedVideoCount','video_count','videoCount']),0);
    if(scout)return {cls:'g',label:'Scout interest'};
    if(pc>=80)return {cls:'g',label:'Match-ready'};
    if(videos===0)return {cls:'a',label:'No video'};
    return {cls:'a',label:'Evidence incomplete'};
  }
  function fieldHeader(title,sub,right){return '<div class="hd"><div><div class="t">'+esc(title)+'</div><div class="sub">'+esc(sub||'')+'</div></div><div class="r">'+(right||'<span class="avm">'+esc(initials(fullName()))+'</span>')+'</div></div>';}

  /* ================= DASHBOARD ================= */
  function fixtureDate(f){return value(f,['fixture_date','fixtureDate','date','kickoff_at']);}
  function fixtureTime(f){return value(f,['fixture_time','fixtureTime','time','kickoff_time'])||'';}
  function opponent(f){return value(f,['opponent','opponent_name','opponentName'])||'Opponent';}
  function venue(f){return value(f,['venue_name','venue','location'])||'';}
  function futureFixtures(fixtures){var today=new Date();today.setHours(0,0,0,0);return fixtures.filter(function(f){var d=new Date(String(fixtureDate(f)||'').slice(0,10)+'T12:00:00');return Number.isNaN(d.getTime())||d>=today;}).sort(function(a,b){return new Date(fixtureDate(a)||'2999-01-01')-new Date(fixtureDate(b)||'2999-01-01');});}
  function pastFixtures(fixtures){var today=new Date();today.setHours(0,0,0,0);return fixtures.filter(function(f){var status=String(value(f,['status','state'])||'').toLowerCase();var d=new Date(String(fixtureDate(f)||'').slice(0,10)+'T12:00:00');return /completed|played|finished/.test(status)||(!Number.isNaN(d.getTime())&&d<today);});}
  function factsSignal(f){var keys=['match_facts_submitted','matchFactsSubmitted','has_match_facts','hasMatchFacts','match_facts_id','matchFactsId'];for(var i=0;i<keys.length;i++)if(Object.prototype.hasOwnProperty.call(f||{},keys[i]))return !!f[keys[i]];return null;}
  function dashboardAttention(players,fixtures,activity){
    var rows=[];
    pastFixtures(fixtures).filter(function(f){return factsSignal(f)===false;}).slice(0,1).forEach(function(f){rows.push({tone:'r',title:'Match Facts missing — '+opponent(f),sub:'Played '+formatDate(fixtureDate(f))+' · nothing recorded yet',label:'Record now',href:'/coach/match-facts?fixtureId='+encodeURIComponent(f.id||'')});});
    players.slice().sort(function(a,b){return completion(a)-completion(b);}).filter(function(p){return completion(p)<80;}).slice(0,1).forEach(function(p){rows.push({tone:'a',title:'Profile incomplete — '+nameOf(p),sub:'Evidence is '+completion(p)+'% complete',label:'Review',href:'/player/profile?id='+encodeURIComponent(p.id||'')});});
    var noVideo=players.filter(function(p){return num(value(p,['approved_video_count','video_count','videoCount']),0)===0;});if(noVideo.length)rows.push({tone:'a',title:noVideo.length+' player'+(noVideo.length===1?'':'s')+' without video',sub:noVideo.slice(0,2).map(nameOf).join(', ')+' — generate upload links',label:'Video Reels',href:'/coach/video-reels'});
    if(activity.length)rows.push({tone:'g',title:value(activity[0],['title'])||'Scout activity waiting',sub:value(activity[0],['body','message'])||'Open the reviewed Scout conversation',label:'Open chat',href:value(activity[0],['actionUrl','action_url'])||'/coach/chat'});
    return rows.slice(0,4);
  }
  function renderDashboard(data){
    var players=data.players,fixtures=data.fixtures,activity=data.activity,archives=data.archives;
    var avg=players.length?Math.round(players.reduce(function(s,p){return s+completion(p);},0)/players.length):0;
    var completed=pastFixtures(fixtures), withFacts=completed.filter(function(f){return factsSignal(f)===true;}).length;
    var coverage=completed.length?withFacts+'/'+completed.length:'—';
    var next=futureFixtures(fixtures)[0];
    var attention=dashboardAttention(players,fixtures,activity);
    var evidence=players.slice().sort(function(a,b){return completion(a)-completion(b);}).slice(0,4);
    var date=new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'});
    var dateMono=new Date().toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'}).toUpperCase();
    var nextHtml=next?'<div style="text-align:right"><div style="font-family:var(--mono);font-size:8.5px;letter-spacing:.1em;color:#B9C4B4">NEXT FIXTURE</div><div style="font-size:11.5px;font-weight:600">vs '+esc(opponent(next))+' · '+esc(formatDate(fixtureDate(next),fixtureTime(next)))+' · '+esc(value(next,['home_or_away','homeOrAway'])||'Home')+'</div></div>':'<div style="text-align:right"><div style="font-family:var(--mono);font-size:8.5px;letter-spacing:.1em;color:#B9C4B4">NEXT FIXTURE</div><div style="font-size:11.5px;font-weight:600">Nothing scheduled</div></div>';
    desk.innerHTML='<div class="panel" style="background:var(--ink);color:#fff;border-color:var(--ink);margin-bottom:12px"><div class="flex"><div><div style="font-family:var(--disp);font-weight:750;font-size:16px">'+esc((new Date().getHours()<12?'Morning':new Date().getHours()<18?'Afternoon':'Evening')+', '+firstName()+'.')+'</div><div style="font-family:var(--mono);font-size:9px;letter-spacing:.08em;color:#B9C4B4;margin-top:3px">'+esc(dateMono+' · '+team()+(age()?' · '+age():''))+'</div></div><div class="right flex" style="gap:14px;align-items:center">'+nextHtml+'<a class="btn sm" style="background:#fff;border-color:#fff;color:var(--ink)" href="/coach/add-player">Add player</a><a class="btn sm" style="background:var(--turf);border-color:var(--turf);color:#fff" href="/coach/match-facts">Record Match Facts</a></div></div></div>'+
      '<div class="g4" style="margin-bottom:12px"><div class="panel"><div class="tag">Squad</div><div style="font-family:var(--disp);font-weight:760;font-size:22px;margin:4px 0 2px">'+players.length+'</div><div class="mut" style="font-size:9.5px">players in your workspace</div></div><div class="panel"><div class="tag">Evidence complete</div><div style="font-family:var(--disp);font-weight:760;font-size:22px;margin:4px 0 2px">'+avg+'%</div><div class="ebar '+evidenceClass(avg)+'"><span class="tr"><i style="width:'+avg+'%"></i></span><b>'+avg+'%</b></div><div class="mut" style="font-size:9.5px;margin-top:3px">average profile evidence</div></div><div class="panel"><div class="tag">Match Facts coverage</div><div style="font-family:var(--disp);font-weight:760;font-size:22px;margin:4px 0 2px">'+coverage+'</div><div class="mut" style="font-size:9.5px">'+(completed.length-withFacts?'<span class="dot r" style="width:7px;height:7px;display:inline-block;margin-right:4px"></span>'+(completed.length-withFacts)+' completed fixture(s) unrecorded':'Recorded evidence is current')+'</div></div><div class="panel"><div class="tag">Estimated squad value</div><div style="font-family:var(--disp);font-weight:760;font-size:22px;margin:4px 0 2px">'+(players.some(function(p){return num(value(p,['transfer_value','estimated_value']),0)>0;})?'Live':'Developing')+'</div><div class="mut" style="font-size:9.5px">evidence-led signal</div></div></div>'+
      '<div class="grid2"><div class="panel rule"><div class="ph3"><b>Needs attention · '+attention.length+'</b><span class="m">generated from your data · each item deep-links to its fix</span></div>'+(attention.length?attention.map(function(r){return '<div class="kv" style="align-items:flex-start"><span class="flex" style="gap:8px;align-items:flex-start"><span class="dot '+r.tone+'" style="margin-top:4px"></span><span><b style="color:var(--ink)">'+esc(r.title)+'</b><br><span style="font-size:9px">'+esc(r.sub)+'</span></span></span><b><a class="btn sm'+(r.tone==='r'?' pri':'')+'" href="'+esc(clean(r.href))+'">'+esc(r.label)+'</a></b></div>';}).join(''):'<div class="mut">Nothing urgent from the data available right now.</div>')+'</div><div><div class="panel rule" style="margin-bottom:12px"><div class="ph3"><b>Upcoming fixtures</b><span class="m">All fixtures</span></div>'+futureFixtures(fixtures).slice(0,2).map(function(f){return '<div class="kv"><span><b style="color:var(--ink)">vs '+esc(opponent(f))+'</b><br><span style="font-size:9px">'+esc(formatDate(fixtureDate(f),fixtureTime(f))+(venue(f)?' · '+venue(f):''))+'</span></span><b><span class="tag">'+esc(value(f,['home_or_away','homeOrAway'])||'Home')+'</span></b></div>';}).join('')+(futureFixtures(fixtures).length?'':'<div class="mut">No upcoming fixture.</div>')+'</div><div class="panel rule"><div class="ph3"><b>Recent scout activity</b><span class="m">'+activity.length+' this week</span></div>'+activity.slice(0,3).map(function(a){return '<div class="kv"><span class="pw"><span class="av">SC</span><span class="who"><b>'+esc(value(a,['title'])||'Scout activity')+'</b><span>'+esc(value(a,['body','message'])||'Reviewed Scout update')+'</span></span></span><b></b></div>';}).join('')+(activity.length?'':'<div class="mut">No new Scout activity.</div>')+'</div></div></div>'+
      '<div class="grid2" style="margin-top:12px"><div class="panel rule"><div class="ph3"><b>Season summary · current</b><span class="m">Previous seasons · '+archives.length+'</span></div><div class="flex" style="gap:16px"><span class="plate"><b>'+completed.length+'</b><span>played</span></span><span class="plate"><b>'+withFacts+'</b><span>recorded</span></span><span class="plate"><b>'+players.reduce(function(s,p){return s+num(value(p,['goals']),0);},0)+'</b><span>goals</span></span><span class="plate g"><b>'+players.reduce(function(s,p){return s+num(value(p,['assists']),0);},0)+'</b><span>assists</span></span></div><div class="mut" style="font-size:9px;margin-top:8px">The evidence pipeline should keep pace with the football.</div></div><div class="panel rule"><div class="ph3"><b>Evidence by player</b><span class="m">weakest first · My Players</span></div>'+evidence.map(function(p){var pc=completion(p);return '<div class="kv"><span>'+esc(nameOf(p))+'</span><b class="ebar '+evidenceClass(pc)+'" style="width:170px"><span class="tr"><i style="width:'+pc+'%"></i></span><b>'+pc+'%</b></b></div>';}).join('')+'</div></div>';

    var mobileAtt=attention.map(function(r){return '<div class="rowline" style="padding:6px 0;border-bottom:1px solid var(--ln)"><span class="dotm '+r.tone+'"></span><span class="who"><b>'+esc(r.title)+'</b><span>'+esc(r.sub)+'</span></span><a class="bt sm '+(r.tone==='r'?'spend':'gh')+'" href="'+esc(clean(r.href))+'">'+esc(r.label.replace(' now',''))+'</a></div>';}).join('');
    field.innerHTML=fieldHeader((new Date().getHours()<12?'Morning':'Afternoon')+', '+firstName(),date+' · '+team()+(age()?' · '+age():''),'<button class="icb" type="button" data-coach-notifications>🔔</button><span class="avm">'+esc(initials(fullName()))+'</span>')+'<div class="stack"><div class="card hero"><div class="ck g">Next fixture'+(next?'':' · not scheduled')+'</div><div style="font-family:var(--disp);font-weight:740;font-size:15px;margin:5px 0 1px">'+(next?'vs '+esc(opponent(next)):'Add your next fixture')+'</div><div class="mut" style="font-size:10px">'+(next?esc(formatDate(fixtureDate(next),fixtureTime(next))+(venue(next)?' · '+venue(next):'')):'Keep Match Facts tied to real match context.')+'</div><div class="flex" style="gap:8px;margin-top:10px"><a class="bt spend" style="flex:1;justify-content:center" href="/coach/match-facts?mode=live">Open Matchday Log</a><a class="bt sm gh" href="/coach/fixtures">Fixture</a></div></div><div class="card rule"><div class="ck" style="margin-bottom:7px">Needs attention · '+attention.length+'</div>'+mobileAtt+'</div><div class="two"><div class="card"><div class="ck">Evidence complete</div><div style="font-family:var(--disp);font-weight:780;font-size:21px;margin-top:3px">'+avg+'%</div><div class="ebm '+evidenceClass(avg)+'" style="margin-top:4px"><span class="tr"><i style="width:'+avg+'%"></i></span><b>'+avg+'%</b></div></div><div class="card"><div class="ck">MF coverage</div><div style="font-family:var(--disp);font-weight:780;font-size:21px;margin-top:3px">'+coverage+'</div><div class="mut" style="font-size:9px">'+(completed.length-withFacts?'<span class="dotm r"></span> '+(completed.length-withFacts)+' unrecorded':'Current')+'</div></div></div><div class="card rule"><div class="flex" style="margin-bottom:7px"><span class="ck">Weakest evidence</span><span class="right"><a class="bt sm gh" href="/coach/my-players">Squad</a></span></div>'+evidence.slice(0,2).map(function(p){var pc=completion(p);return '<a class="rowline" href="/player/profile?id='+encodeURIComponent(p.id||'')+'" style="padding:5px 0;border-bottom:1px solid var(--ln);text-decoration:none"><span class="avm">'+esc(initials(nameOf(p)))+'</span><span class="who"><b>'+esc(nameOf(p)+' · '+position(p))+'</b><span>'+esc(tagForPlayer(p,pc).label.toLowerCase())+'</span></span><span class="ebm '+evidenceClass(pc)+'" style="width:86px"><span class="tr"><i style="width:'+pc+'%"></i></span><b>'+pc+'%</b></span></a>';}).join('')+'</div></div>';
  }
  async function initDashboard(){
    try{
      var rs=await Promise.allSettled([api('GET','/api/coaches/my-players'),api('GET','/api/fixtures'),api('GET','/api/notifications?limit=20'),api('GET','/api/season/archives')]);
      renderDashboard({players:rs[0].status==='fulfilled'?list(rs[0].value,['players','data']):[],fixtures:rs[1].status==='fulfilled'?list(rs[1].value,['fixtures','data']):[],activity:rs[2].status==='fulfilled'?list(rs[2].value,['notifications','data']):[],archives:rs[3].status==='fulfilled'?list(rs[3].value,['archives','data']):[]});
    }catch(e){desk.innerHTML=routeMessage(e.message||'Dashboard could not load.',true);field.innerHTML=routeMessage(e.message||'Dashboard could not load.',true);}
  }

  /* ================= MY PLAYERS ================= */
  function currentPlayers(){var q=String(state.playerSearch||'').toLowerCase(),pg=state.playerPosition||'',rows=(state.players||[]).filter(function(p){return(!q||nameOf(p).toLowerCase().indexOf(q)>=0)&&(!pg||positionGroup(p)===pg)&&(!state.needsWork||completion(p)<100);});rows.sort(function(a,b){if(state.playerSort==='name')return nameOf(a).localeCompare(nameOf(b));if(state.playerSort==='overall')return num(value(b,['overall_rating','overall']),-1)-num(value(a,['overall_rating','overall']),-1);return completion(a)-completion(b);});return rows;}
  function coachOptions(selected){return (state.coaches||[]).map(function(c){return '<option value="'+esc(c.id)+'"'+(String(c.id)===String(selected)?' selected':'')+'>'+esc([c.first_name,c.last_name].filter(Boolean).join(' ')||'Coach')+(c.is_super_user?' (Super user)':'')+'</option>';}).join('');}
  function renderPlayers(){
    var rows=currentPlayers(),pages=Math.max(1,Math.ceil(rows.length/14));state.playerPage=Math.min(state.playerPage||1,pages);var slice=rows.slice((state.playerPage-1)*14,state.playerPage*14);
    desk.innerHTML='<div class="flex" style="gap:8px;margin-bottom:10px"><label class="sel" style="min-width:190px"><input id="playerSearch" type="search" value="'+esc(state.playerSearch||'')+'" placeholder="Search '+state.players.length+' players…" style="border:0;background:transparent;outline:0;width:100%"></label>'+['','GK','DEF','MID','ATT'].map(function(g){return '<button type="button" class="chip '+((state.playerPosition||'')===g?'on':'')+'" data-pos="'+g+'">'+(g||'All positions')+'</button>';}).join('')+'<button type="button" class="chip '+(state.needsWork?'on':'')+'" id="evidenceToggle">Evidence: '+(state.needsWork?'needs work':'all')+'</button><span class="right mut" style="font-size:9px">Sorted: '+(state.playerSort==='evidence'?'Evidence ↑':state.playerSort==='name'?'Name':'Overall ↓')+' · '+rows.length+' players · page '+state.playerPage+' of '+pages+'</span></div><div class="panel rule" style="padding:0"><table class="t"><thead><tr><th>Player</th><th>Position</th><th>Apps</th><th>G</th><th>A</th><th>Overall</th><th>Evidence</th><th>Value</th><th>Assigned coach</th><th>Status</th><th></th></tr></thead><tbody>'+slice.map(function(p){var pc=completion(p),tag=tagForPlayer(p,pc),assigned=value(p,['assigned_coach_id','assignedCoachId','coach_id']);return '<tr data-player-id="'+esc(p.id||'')+'"><td><a class="pw" href="/player/profile?id='+encodeURIComponent(p.id||'')+'" style="text-decoration:none"><span class="av '+(tag.label==='Scout interest'?'g':'')+'">'+esc(initials(nameOf(p)))+'</span><span class="who"><b>'+esc(nameOf(p))+'</b><span>'+esc(team())+'</span></span></a></td><td>'+esc(position(p)+' · '+(value(p,['age_group','ageGroup'])||'—'))+'</td><td>'+num(value(p,['appearances','apps']),0)+'</td><td>'+num(value(p,['goals']),0)+'</td><td>'+num(value(p,['assists']),0)+'</td><td class="mono">'+(value(p,['overall_rating','overall'])==null?'—':Math.round(num(value(p,['overall_rating','overall']),0)))+'</td><td><span class="ebar '+evidenceClass(pc)+'"><span class="tr"><i style="width:'+pc+'%"></i></span><b>'+pc+'%</b></span></td><td>'+esc(fmtMoney(value(p,['transfer_value','estimated_value'])))+'</td><td>'+(state.isSuper&&state.coaches.length?'<select class="sel" data-assign="'+esc(p.id)+'">'+coachOptions(assigned||state.profile.id)+'</select>':esc(value(p,['assigned_coach_name'])||fullName()))+'</td><td><span class="tag '+tag.cls+'">'+esc(tag.label)+'</span></td><td><span class="coach-relative"><button class="btn sm gh" type="button" data-player-menu="'+esc(p.id)+'">⋯</button></span></td></tr>';}).join('')+'</tbody></table><div class="flex" style="padding:9px 14px;border-top:1px solid var(--ln)"><span class="mut" style="font-size:9px">Showing '+slice.length+' of '+rows.length+' · row click opens the Player Profile</span><span class="right coach-pager"><button class="btn sm gh" data-page="'+Math.max(1,state.playerPage-1)+'">← Prev</button>'+Array.from({length:pages},function(_,i){return '<button class="chip '+(i+1===state.playerPage?'on':'')+'" data-page="'+(i+1)+'">'+(i+1)+'</button>';}).join('')+'<button class="btn sm gh" data-page="'+Math.min(pages,state.playerPage+1)+'">Next →</button></span></div></div>';
    var mob=slice.slice().sort(function(a,b){return completion(a)-completion(b);});
    field.innerHTML=fieldHeader('Squad',state.players.length+' players · '+team()+(age()?' · '+age():''),'<a class="bt sm spend" href="/coach/add-player">Add</a>')+'<div class="stack"><label class="srch"><input id="fieldPlayerSearch" type="search" value="'+esc(state.playerSearch||'')+'" placeholder="Search '+state.players.length+' players…" style="border:0;background:transparent;outline:0;width:100%"></label><div class="seg">'+['','GK','DEF','MID','ATT'].map(function(g){return '<a href="#" class="'+((state.playerPosition||'')===g?'on':'')+'" data-field-pos="'+g+'">'+(g||'All')+'</a>';}).join('')+'</div><div class="flex" style="gap:6px"><button class="chip '+(state.needsWork?'on':'')+'" id="fieldNeeds">Needs work</button><span class="chip">Scout interest</span><span class="chip">Match-ready</span></div><div class="card rule" style="padding:10px 12px">'+mob.map(function(p){var pc=completion(p),tag=tagForPlayer(p,pc);return '<a class="rowline" href="/player/profile?id='+encodeURIComponent(p.id||'')+'" style="padding:7px 0;border-bottom:1px solid var(--ln);text-decoration:none"><span class="avm '+(tag.label==='Scout interest'?'g':'')+'">'+esc(initials(nameOf(p)))+'</span><span class="who"><b>'+esc(nameOf(p)+' · '+position(p))+'</b><span>'+num(value(p,['appearances','apps']),0)+' apps · '+esc(tag.label.toLowerCase())+'</span></span><span class="ebm '+evidenceClass(pc)+'" style="width:80px"><span class="tr"><i style="width:'+pc+'%"></i></span><b>'+pc+'%</b></span></a>';}).join('')+'</div><div class="mut" style="font-size:9px;text-align:center">Sorted weakest first when “Needs work” is on · full table, sorting and CSV live on Coach Desk</div></div>';
    bindPlayers();
  }
  function bindPlayers(){
    function q(id){return document.getElementById(id);} var s=q('playerSearch'),fs=q('fieldPlayerSearch');[s,fs].forEach(function(n){if(n)n.addEventListener('input',function(){state.playerSearch=n.value;renderPlayers();});});
    document.querySelectorAll('[data-pos],[data-field-pos]').forEach(function(b){b.addEventListener('click',function(e){e.preventDefault();state.playerPosition=b.getAttribute('data-pos')!=null?b.getAttribute('data-pos'):b.getAttribute('data-field-pos');state.playerPage=1;renderPlayers();});});
    ['evidenceToggle','fieldNeeds'].forEach(function(id){var b=q(id);if(b)b.addEventListener('click',function(){state.needsWork=!state.needsWork;state.playerPage=1;renderPlayers();});});
    document.querySelectorAll('[data-page]').forEach(function(b){b.addEventListener('click',function(){state.playerPage=Number(b.dataset.page)||1;renderPlayers();});});
    document.querySelectorAll('[data-assign]').forEach(function(sel){sel.addEventListener('change',function(){var pid=sel.dataset.assign,cid=sel.value;api('POST','/api/coaches/assign-player/'+encodeURIComponent(pid),{coachId:cid}).then(function(){window.CoachV2.showToast('Player assignment updated.');}).catch(function(e){window.alert(e.message);});});});
    document.querySelectorAll('[data-player-menu]').forEach(function(b){b.addEventListener('click',function(){var pid=b.dataset.playerMenu,p=state.players.find(function(x){return String(x.id)===String(pid);});window.CoachV2.openDrawer({title:nameOf(p),html:'<div class="stack"><a class="btn pri" href="/player/profile?id='+encodeURIComponent(pid)+'">Open profile</a><a class="btn gh" href="/player/profile?id='+encodeURIComponent(pid)+'&edit=1">Edit</a><button class="btn gh" id="generatePlayerLink" type="button">Generate video link</button><div id="playerLinkResult"></div></div>'});setTimeout(function(){var g=document.getElementById('generatePlayerLink');if(g)g.onclick=function(){api('POST','/api/videos/upload-link',{playerId:pid}).then(function(r){var d=r.data||r;document.getElementById('playerLinkResult').innerHTML='<div class="linkbox">'+esc(d.uploadUrl||d.url||'Link created')+'</div>';});};},0);});});
    var exp=document.getElementById('coachExportPlayers');if(exp)exp.onclick=exportPlayers;
  }
  function exportPlayers(){var rows=currentPlayers(),csv=['Player,Position,Age group,Apps,Goals,Assists,Overall,Evidence'];rows.forEach(function(p){csv.push([nameOf(p),position(p),value(p,['age_group'])||'',num(value(p,['appearances','apps']),0),num(value(p,['goals']),0),num(value(p,['assists']),0),value(p,['overall_rating','overall'])||'',completion(p)+'%'].map(function(v){return '"'+String(v).replace(/"/g,'""')+'"';}).join(','));});var blob=new Blob([csv.join('\n')],{type:'text/csv'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='scoutlink-my-players.csv';a.click();URL.revokeObjectURL(url);}
  async function initPlayers(){
    state.playerSearch='';state.playerPosition='';state.playerSort='evidence';state.playerPage=1;state.needsWork=true;
    try{var rs=await Promise.allSettled([api('GET','/api/coaches/my-players'),api('GET','/api/coaches/profile')]);state.players=rs[0].status==='fulfilled'?list(rs[0].value,['players','data']):[];state.profile=rs[1].status==='fulfilled'?(rs[1].value.coach||rs[1].value):{};state.isSuper=!!state.profile.is_super_user;state.coaches=[];if(state.isSuper){var cr=await api('GET','/api/coaches/team-coaches');state.coaches=[state.profile].concat(list(cr,['coaches','data'])).filter(function(c,i,a){return c&&c.id&&a.findIndex(function(x){return x&&String(x.id)===String(c.id);})===i;});}renderPlayers();}catch(e){desk.innerHTML=routeMessage(e.message,true);field.innerHTML=routeMessage(e.message,true);}
  }

  /* ================= FIXTURES ================= */
  function matchFactMap(facts){var m={};facts.forEach(function(x){var id=value(x,['fixture_id','fixtureId']);if(id)m[String(id)]=x;});return m;}
  function fixtureStatus(f,facts){var now=new Date();now.setHours(0,0,0,0);var d=new Date(String(fixtureDate(f)||'').slice(0,10)+'T12:00:00');var upcoming=Number.isNaN(d.getTime())||d>=now; if(upcoming)return'upcoming';if(facts[String(f.id)])return'recorded';try{var dr=JSON.parse(localStorage.getItem('scoutlink.coach.matchFacts.v5')||'null');if(dr&&dr.state&&String(dr.state.fixtureId)===String(f.id))return'draft';}catch(_){}return'missing';}
  function fixtureRow(f,status,mobile){var cls=status==='missing'?'r':status==='draft'?'a':'g';var score=(f.home_score!=null||f.away_score!=null)?' · '+num(f.home_score,0)+'–'+num(f.away_score,0):'';var action=status==='missing'?'<a class="'+(mobile?'bt':'btn')+' sm '+(mobile?'spend':'pri')+'" href="/coach/match-facts?fixtureId='+encodeURIComponent(f.id||'')+'">'+(mobile?'Prepare':'Prepare Match Facts')+'</a>':status==='draft'?'<a class="'+(mobile?'bt':'btn')+' sm gh" href="/coach/match-facts?fixtureId='+encodeURIComponent(f.id||'')+'">Resume'+(mobile?'':' Match Facts')+'</a>':status==='recorded'?'<span class="'+(mobile?'tagm':'tag')+' g">Recorded</span>':'<button class="'+(mobile?'bt':'btn')+' sm gh" data-edit-fixture="'+esc(f.id)+'">Edit</button>';
    if(mobile)return '<div class="rowline" style="padding:6px 0;border-bottom:1px solid var(--ln)">'+(status!=='upcoming'?'<span class="dotm '+cls+'"></span>':'')+'<span class="who"><b>vs '+esc(opponent(f))+esc(score)+'</b><span>'+esc(formatDate(fixtureDate(f),fixtureTime(f))+' · '+(value(f,['home_or_away'])||'Home'))+'</span></span>'+action+'</div>';
    return '<div class="kv"><span class="flex" style="gap:8px">'+(status!=='upcoming'?'<span class="dot '+cls+'" style="margin-top:4px"></span>':'')+'<span><b style="color:var(--ink)">vs '+esc(opponent(f))+esc(score)+'</b><br><span style="font-size:9px">'+esc(formatDate(fixtureDate(f),fixtureTime(f))+(venue(f)?' · '+venue(f):'')+' · '+(value(f,['home_or_away'])||'Home'))+'</span></span></span><b class="flex" style="gap:6px">'+(status==='upcoming'?'<button class="btn sm gh" data-edit-fixture="'+esc(f.id)+'">Edit</button><button class="btn sm gh" style="border-color:var(--rd);color:var(--rd)" data-delete-fixture="'+esc(f.id)+'">Delete</button>':action)+'</b></div>';
  }
  function renderFixtures(){var fmap=matchFactMap(state.matchFacts||[]),up=(state.fixtures||[]).filter(function(f){return fixtureStatus(f,fmap)==='upcoming';}),done=(state.fixtures||[]).filter(function(f){return fixtureStatus(f,fmap)!=='upcoming';});var miss=done.filter(function(f){return fixtureStatus(f,fmap)==='missing';}).length;
    desk.innerHTML='<div class="flex" style="gap:8px;margin-bottom:10px"><button class="chip on">Upcoming · '+up.length+'</button><button class="chip">Completed · '+done.length+'</button><button class="chip">Missing Match Facts · '+miss+'</button></div><div class="panel rule" style="margin-bottom:12px"><div class="ph3"><b>Upcoming</b></div>'+(up.length?up.map(function(f){return fixtureRow(f,'upcoming',false);}).join(''):'<div class="mut">No upcoming fixtures.</div>')+'</div><div class="panel rule"><div class="ph3"><b>Completed</b><span class="m">state decides the action</span></div>'+(done.length?done.map(function(f){return fixtureRow(f,fixtureStatus(f,fmap),false);}).join(''):'<div class="mut">No completed fixtures.</div>')+'</div><input type="file" id="fixtureCsvInput" accept=".csv" hidden>';
    field.innerHTML=fieldHeader('Fixtures',up.length+' upcoming · '+done.length+' completed · '+miss+' missing MF','<button class="bt sm spend" id="fieldAddFixture">Add</button>')+'<div class="stack"><div class="dateplate">UPCOMING</div><div class="card rule" style="padding:10px 12px">'+(up.length?up.map(function(f){return fixtureRow(f,'upcoming',true);}).join(''):'<div class="mut">No upcoming fixtures.</div>')+'</div><div class="dateplate">COMPLETED</div><div class="card rule" style="padding:10px 12px">'+(done.length?done.map(function(f){return fixtureRow(f,fixtureStatus(f,fmap),true);}).join(''):'<div class="mut">No completed fixtures.</div>')+'</div><div class="mut" style="font-size:9px;text-align:center">Season CSV import lives on Coach Desk → Fixtures</div></div>';
    bindFixtureActions();
  }
  function fixtureForm(f){f=f||{};return '<form id="fixtureForm"><div class="field"><label>Opponent <i>Required</i></label><input name="opponent" value="'+esc(opponent(f)==='Opponent'?'':opponent(f))+'"></div><div class="two"><div class="field"><label>Date <i>Required</i></label><input name="fixtureDate" type="date" value="'+esc(String(fixtureDate(f)||'').slice(0,10))+'"></div><div class="field"><label>Kick-off</label><input name="fixtureTime" type="time" value="'+esc(String(fixtureTime(f)||'').slice(0,5))+'"></div></div><div class="field"><label>Venue</label><input name="venueName" value="'+esc(venue(f))+'"></div><div class="two"><div class="field"><label>Home / away</label><select name="homeOrAway"><option'+((value(f,['home_or_away'])||'Home')==='Home'?' selected':'')+'>Home</option><option'+(value(f,['home_or_away'])==='Away'?' selected':'')+'>Away</option></select></div><div class="field"><label>Format</label><select name="format"><option>11-a-side</option><option>9-a-side</option><option>7-a-side</option><option>5-a-side</option></select></div></div><div class="field"><label>Notes</label><textarea name="notes">'+esc(value(f,['notes'])||'')+'</textarea></div><div id="fixtureFormMsg" class="mut"></div><div class="flex" style="justify-content:flex-end"><button class="btn pri" type="submit">Save fixture</button></div></form>';}
  function openFixture(f){var box=window.CoachV2.openDrawer({title:f?'Edit fixture':'Add fixture',html:fixtureForm(f)});setTimeout(function(){var form=document.getElementById('fixtureForm');if(form)form.onsubmit=function(e){e.preventDefault();var fd=new FormData(form),body={};fd.forEach(function(v,k){body[k]=v||null;});body.opponent=String(body.opponent||'').trim();if(!body.opponent||!body.fixtureDate){document.getElementById('fixtureFormMsg').textContent='Opponent and date are required.';return;}api(f?'PUT':'POST',f?'/api/fixtures/'+encodeURIComponent(f.id):'/api/fixtures',body).then(function(){window.CoachV2.closeAll();return loadFixtures();}).catch(function(err){document.getElementById('fixtureFormMsg').textContent=err.message;});};},0);return box;}
  function bindFixtureActions(){document.querySelectorAll('[data-edit-fixture]').forEach(function(b){b.onclick=function(){openFixture(state.fixtures.find(function(f){return String(f.id)===String(b.dataset.editFixture);})||null);};});document.querySelectorAll('[data-delete-fixture]').forEach(function(b){b.onclick=function(){var f=state.fixtures.find(function(x){return String(x.id)===String(b.dataset.deleteFixture);});if(f&&confirm('Delete the fixture against '+opponent(f)+'?'))api('DELETE','/api/fixtures/'+encodeURIComponent(f.id),{}).then(loadFixtures).catch(function(e){alert(e.message);});};});var add=document.getElementById('coachAddFixture'),fa=document.getElementById('fieldAddFixture');if(add)add.onclick=function(){openFixture(null);};if(fa)fa.onclick=function(){openFixture(null);};var imp=document.getElementById('coachImportFixtures'),inp=document.getElementById('fixtureCsvInput');if(imp&&inp){imp.onclick=function(){inp.click();};inp.onchange=function(){if(inp.files[0])importFixtureCsv(inp.files[0]);};}}
  function importFixtureCsv(file){file.text().then(function(text){var lines=text.split(/\r?\n/).filter(Boolean);if(lines.length<2)throw new Error('CSV has no fixture rows.');var h=lines[0].split(',').map(function(x){return x.trim().toLowerCase().replace(/[^a-z0-9]+/g,'_');});var rows=lines.slice(1).map(function(line){var v=line.split(',');var r={};h.forEach(function(k,i){r[k]=(v[i]||'').trim();});return{opponent:r.opponent||r.opponent_name,fixtureDate:r.fixture_date||r.date,fixtureTime:r.fixture_time||r.time||null,venueName:r.venue||r.venue_name||null,homeOrAway:r.home_or_away||r.home_away||'Home',format:r.format||'11-a-side'};}).filter(function(r){return r.opponent&&r.fixtureDate;});return rows.reduce(function(p,r){return p.then(function(){return api('POST','/api/fixtures',r);});},Promise.resolve());}).then(function(){window.CoachV2.showToast('Fixture CSV imported.');return loadFixtures();}).catch(function(e){alert(e.message);});}
  async function loadFixtures(){try{var rs=await Promise.all([api('GET','/api/fixtures?upcoming=true').catch(function(){return{data:[]};}),api('GET','/api/fixtures?past=true').catch(function(){return{data:[]};}),api('GET','/api/match-facts?limit=100').catch(function(){return{data:[]};})]);var seen={};state.fixtures=list(rs[0],['fixtures','data']).concat(list(rs[1],['fixtures','data'])).filter(function(f){var k=String(f.id||opponent(f)+fixtureDate(f));if(seen[k])return false;seen[k]=1;return true;});state.matchFacts=list(rs[2],['matchFacts','data']);renderFixtures();}catch(e){desk.innerHTML=routeMessage(e.message,true);field.innerHTML=routeMessage(e.message,true);}}

  /* ================= VIDEO REELS ================= */
  function videoUrl(v){return value(v,['url','video_url','file_url','signed_url'])||'';}
  function renderVideos(){var videos=state.videos||[],players=state.videoPlayers||[],pending=videos.filter(function(v){return String(value(v,['status'])||'approved').toLowerCase()==='pending'||value(v,['approved'])===false;}),approved=videos.filter(function(v){return pending.indexOf(v)<0;});
    var cards=approved.map(function(v){return '<div class="vidt"><div class="th" data-watch-video="'+esc(videoUrl(v))+'">▶<span class="du">VIDEO</span></div><div class="bd"><b>'+esc(value(v,['title'])||'Video reel')+'</b><span>'+esc(value(v,['player_name'])||value(v,['category'])||'Approved video')+'</span><div class="flex" style="gap:6px;margin-top:5px"><button class="btn sm gh" data-watch-video="'+esc(videoUrl(v))+'">Open</button><button class="btn sm gh" style="border-color:var(--rd);color:var(--rd)" data-delete-video="'+esc(v.id||'')+'">Delete</button></div></div></div>';}).join('');
    desk.innerHTML='<div class="panel rule" style="border-top-color:var(--am);margin-bottom:12px"><div class="ph3"><b>Awaiting your review · '+pending.length+'</b><span class="m">not visible to scouts until approved</span></div>'+(pending.length?pending.map(function(v){return '<div class="kv"><span class="pw"><span class="av">'+esc(initials(value(v,['player_name'])||'PL'))+'</span><span class="who"><b>New clip via upload link — '+esc(value(v,['player_name'])||'Player')+'</b><span>'+esc(value(v,['title','file_name'])||'Video received')+'</span></span></span><b><button class="btn sm gh" data-watch-video="'+esc(videoUrl(v))+'">Preview</button></b></div>';}).join(''):'<div class="mut">No clips are waiting for review.</div>')+'</div><div style="display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:12px;align-items:start"><div class="panel rule"><div class="ph3"><b>All videos · '+approved.length+'</b></div><div class="flex" style="gap:6px;margin-bottom:10px"><span class="chip on">All</span><span class="chip">Highlight</span><span class="chip">Match</span><span class="chip">Training</span><span class="chip">Skills</span><span class="chip">Goal</span></div><div class="three" style="gap:10px">'+(cards||'<div class="mut">No approved videos yet.</div>')+'</div></div><div><div class="panel rule" style="margin-bottom:12px"><div class="ph3"><b>Upload Video Reel</b></div><form id="videoUploadForm"><div class="field"><label>Player <i>Required</i></label><select name="playerId"><option value="">Select player…</option>'+players.map(function(p){return '<option value="'+esc(p.id)+'">'+esc(nameOf(p))+'</option>';}).join('')+'</select></div><div class="two"><div class="field"><label>Category</label><select name="category"><option>Highlight</option><option>Match</option><option>Training</option><option>Skills</option><option>Goal</option></select></div><div class="field"><label>Title</label><input name="title" placeholder="Optional title"></div></div><label class="drop"><b>Drop file or browse</b><input name="file" type="file" accept="video/*" style="margin-top:7px">MP4 / MOV / WEBM / AVI · max 100MB</label><div id="videoUploadMsg" class="mut"></div><div class="flex" style="justify-content:flex-end;margin-top:10px"><button class="btn pri" type="submit">Upload Video</button></div></form></div><div class="panel rule" style="border-top-color:var(--pitch)"><div class="ph3"><b>Player Upload Link</b><span class="m">Safeguarded</span></div><div class="field"><label>Player <i>Required</i></label><select id="videoLinkPlayer"><option value="">Select player…</option>'+players.map(function(p){return '<option value="'+esc(p.id)+'">'+esc(nameOf(p))+'</option>';}).join('')+'</select></div><button class="btn pri" id="generateVideoLink">Generate Link</button><div id="videoLinkResult" style="margin-top:8px"></div><div class="mut" style="font-size:9px;margin-top:8px"><b style="color:var(--ink)">Send through an approved adult channel.</b> Token-protected and single-player; uploads are reviewed before scout visibility.</div></div></div></div>';
    field.innerHTML=fieldHeader('Video Reels',approved.length+' videos','<span class="avm">'+esc(initials(fullName()))+'</span>')+'<div class="stack"><div class="card rule" style="border-top-color:var(--am)"><div class="ck">Awaiting review · '+pending.length+'</div>'+(pending.length?pending.map(function(v){return '<div class="rowline" style="padding:7px 0"><span class="who"><b>'+esc(value(v,['player_name'])||'Player')+'</b><span>'+esc(value(v,['title'])||'New clip')+'</span></span><button class="bt sm gh" data-watch-video="'+esc(videoUrl(v))+'">Preview</button></div>';}).join(''):'<div class="mut" style="margin-top:6px">No clips are waiting.</div>')+'</div><div class="seg"><a class="on">All</a><a>Highlight</a><a>Match</a><a>Training</a><a>Goal</a></div><div class="two">'+approved.slice(0,6).map(function(v){return '<div class="vidm"><div class="th" data-watch-video="'+esc(videoUrl(v))+'">▶<span class="du">VIDEO</span></div><div class="bd"><b>'+esc(value(v,['title'])||'Video reel')+'</b><span>'+esc(value(v,['player_name'])||value(v,['category'])||'Approved')+'</span></div></div>';}).join('')+'<button class="vidm" id="fieldUploadVideo" type="button" style="padding:0;text-align:left"><div class="th" style="background:var(--pn2);color:var(--faint)">+</div><div class="bd"><b>Upload</b><span>or generate a link</span></div></button></div></div>';
    bindVideoActions();
  }
  function bindVideoActions(){document.querySelectorAll('[data-watch-video]').forEach(function(b){b.onclick=function(){var url=b.dataset.watchVideo;if(!url)return alert('Video URL is unavailable.');window.open(url,'_blank','noopener');};});document.querySelectorAll('[data-delete-video]').forEach(function(b){b.onclick=function(){if(confirm('Delete this video?'))api('DELETE','/api/videos/'+encodeURIComponent(b.dataset.deleteVideo),{}).then(loadVideos).catch(function(e){alert(e.message);});};});var refresh=document.getElementById('coachRefreshVideos');if(refresh)refresh.onclick=loadVideos;var gen=document.getElementById('generateVideoLink');if(gen)gen.onclick=function(){var pid=document.getElementById('videoLinkPlayer').value;if(!pid)return;gen.disabled=true;api('POST','/api/videos/upload-link',{playerId:pid}).then(function(r){var d=r.data||r,url=d.uploadUrl||d.url||'';document.getElementById('videoLinkResult').innerHTML='<div class="linkbox">'+esc(url||'Link created')+'<span class="right"><button class="btn sm" id="copyVideoLink">Copy Link</button></span></div>';var c=document.getElementById('copyVideoLink');if(c)c.onclick=function(){navigator.clipboard.writeText(url);window.CoachV2.showToast('Link copied.');};}).catch(function(e){document.getElementById('videoLinkResult').textContent=e.message;}).finally(function(){gen.disabled=false;});};var form=document.getElementById('videoUploadForm');if(form)form.onsubmit=uploadVideo;var fu=document.getElementById('fieldUploadVideo');if(fu)fu.onclick=openFieldVideoSheet;}
  function uploadVideo(e){e.preventDefault();var form=e.currentTarget,fd0=new FormData(form),file=fd0.get('file'),msg=document.getElementById('videoUploadMsg');if(!fd0.get('playerId')||!file||!file.size){msg.textContent='Choose a player and video file.';return;}if(file.size>100*1024*1024){msg.textContent='Video files must be 100MB or smaller.';return;}var fd=new FormData();fd.append('file',file);fd.append('title',fd0.get('title')||file.name);fd.append('category',fd0.get('category')||'Highlight');fd.append('playerId',fd0.get('playerId'));msg.textContent='Uploading…';fetch((window.API||'')+'/api/videos/upload',{method:'POST',headers:{Authorization:'Bearer '+(window.Auth&&window.Auth.token||'')},body:fd}).then(function(r){return r.json().then(function(d){if(!r.ok)throw new Error(d.error||'Upload failed');return d;});}).then(function(){window.CoachV2.showToast('Video uploaded.');return loadVideos();}).catch(function(e2){msg.textContent=e2.message;});}
  function openFieldVideoSheet(){window.CoachV2.openSheet({title:'Upload Video Reel',html:'<div class="stack"><div class="mut">Use Coach Desk for the full upload form, or generate a safeguarded player upload link from the Video Reels page.</div><a class="bt pri blk" href="/coach/video-reels">Open Video Reels</a></div>'});}
  async function loadVideos(){try{var rs=await Promise.all([api('GET','/api/videos?type=player').catch(function(){return{data:[]};}),api('GET','/api/coaches/my-players').catch(function(){return{data:[]};})]);state.videos=list(rs[0],['videos','data']);state.videoPlayers=list(rs[1],['players','data']);renderVideos();}catch(e){desk.innerHTML=routeMessage(e.message,true);field.innerHTML=routeMessage(e.message,true);}}

  /* ================= CHAT ================= */
  function threadId(t){return value(t,['id','thread_id','threadId']);}
  function threadPlayer(t){return value(t,['player_name','playerName'])||nameOf(t.player||{});}
  function threadScout(t){return value(t,['scout_name','scoutName','other_user_name','otherUserName','title'])||'ScoutLink';}
  async function loadThread(id){state.activeThread=String(id||'');try{var r=await api('GET','/api/chat/threads/'+encodeURIComponent(id)+'/messages');state.messages=list(r,['messages','data']);renderChat();}catch(e){state.messages=[];state.chatError=e.message;renderChat();}}
  function renderChat(){var threads=state.threads||[],active=threads.find(function(t){return String(threadId(t))===String(state.activeThread);})||threads[0]||null;if(active&&!state.activeThread)state.activeThread=String(threadId(active));var messages=state.messages||[];
    desk.innerHTML='<div style="display:grid;grid-template-columns:272px minmax(0,1fr);gap:12px;align-items:stretch"><div class="panel" style="padding:0;display:flex;flex-direction:column"><div class="ph3" style="padding:11px 14px;border-bottom:2px solid var(--ink);margin:0"><b>Conversations</b><span class="m">'+threads.length+'</span></div>'+threads.map(function(t){var on=String(threadId(t))===String(state.activeThread);return '<button class="thr '+(on?'on':'')+'" type="button" data-thread="'+esc(threadId(t))+'" style="width:100%;text-align:left"><span class="av">'+esc(initials(threadScout(t)))+'</span><span class="who"><b>'+esc(threadScout(t))+'</b><span><span class="tag g">Reviewed Scout</span> · about '+esc(threadPlayer(t))+'</span></span>'+(num(value(t,['unread_count','unreadCount']),0)?'<span class="un">'+num(value(t,['unread_count','unreadCount']),0)+'</span>':'')+'</button>';}).join('')+'</div><div class="panel" style="padding:0;display:flex;flex-direction:column">'+(active?'<div class="chath"><span class="av">'+esc(initials(threadScout(active)))+'</span><span class="who"><b>'+esc(threadScout(active))+' <span class="tag g" style="margin-left:4px">Reviewed Scout</span></b><span>conversation about <b>'+esc(threadPlayer(active))+'</b></span></span><span class="right flex" style="gap:6px"><a class="btn sm gh" href="/player/profile?id='+encodeURIComponent(value(active,['player_id','playerId'])||'')+'">Open player profile</a><a class="btn sm gh" style="border-color:var(--rd);color:var(--rd)" href="/coach/report-a-concern">Report a concern</a></span></div><div class="chatlog" style="flex:1">'+(state.chatError?routeMessage(state.chatError,true):messages.map(function(m){var mine=String(value(m,['sender_role','senderRole'])||'').toLowerCase()==='coach'||String(value(m,['sender_id','senderId'])||'')===String(user().id||'');return '<div class="msgd '+(mine?'me':'')+'"><span class="au">'+esc(mine?'You':value(m,['sender_name','senderName'])||threadScout(active))+'</span>'+esc(value(m,['body','message','text'])||'')+'<span class="tm">'+esc(formatDate(value(m,['created_at','createdAt'])) )+'</span></div>';}).join(''))+'</div><form class="compose" id="chatCompose"><textarea id="chatMessage" class="sel" style="flex:1;resize:none" rows="2" placeholder="Write a message…"></textarea><button class="btn pri" type="submit">Send</button></form>':'<div class="mut" style="padding:20px">No player conversations yet.</div>')+'</div></div>';
    field.innerHTML=active?fieldHeader(threadScout(active),'Reviewed Scout · about '+threadPlayer(active),'<span class="icb" id="fieldThreadBack">‹</span>')+'<div class="flex" style="gap:6px;margin-bottom:8px"><a class="bt sm gh" href="/player/profile?id='+encodeURIComponent(value(active,['player_id','playerId'])||'')+'">Open player profile</a><a class="bt sm gh" style="border-color:var(--rd);color:var(--rd)" href="/coach/report-a-concern">Report a concern</a></div><div class="stack coach-field-with-actbar" style="--g:8px">'+messages.map(function(m){var mine=String(value(m,['sender_role','senderRole'])||'').toLowerCase()==='coach'||String(value(m,['sender_id','senderId'])||'')===String(user().id||'');return '<div class="msg '+(mine?'me':'them')+'">'+esc(value(m,['body','message','text'])||'')+'<span class="tm">'+esc(formatDate(value(m,['created_at','createdAt'])))+'</span></div>';}).join('')+'</div><form class="actbar" id="fieldChatCompose"><textarea id="fieldChatMessage" class="srch" style="flex:1;resize:none" rows="1" placeholder="Write a message…"></textarea><button class="bt pri" type="submit">Send</button></form>':fieldHeader('Inbox','Player conversations','')+'<div class="card rule">No player conversations yet.</div>';
    bindChat();
  }
  function sendChat(text){var body=String(text||'').trim();if(!body||!state.activeThread)return Promise.resolve();return api('POST','/api/chat/threads/'+encodeURIComponent(state.activeThread)+'/messages',{body:body}).then(function(){return loadThread(state.activeThread);});}
  function bindChat(){document.querySelectorAll('[data-thread]').forEach(function(b){b.onclick=function(){loadThread(b.dataset.thread);};});var f=document.getElementById('chatCompose');if(f)f.onsubmit=function(e){e.preventDefault();var t=document.getElementById('chatMessage');sendChat(t.value).then(function(){t.value='';});};var ff=document.getElementById('fieldChatCompose');if(ff)ff.onsubmit=function(e){e.preventDefault();var t=document.getElementById('fieldChatMessage');sendChat(t.value).then(function(){t.value='';});};}
  async function initChat(){try{var r=await api('GET','/api/chat/threads');state.threads=list(r,['threads','data']).filter(function(t){return value(t,['player_id','playerId'])||t.player;});var requested=new URLSearchParams(location.search).get('threadId');var first=requested||threadId(state.threads[0]);if(first)await loadThread(first);else renderChat();}catch(e){desk.innerHTML=routeMessage(e.message,true);field.innerHTML=routeMessage(e.message,true);}}

  /* ================= NOTIFICATIONS ================= */
  function notifGroup(n){return String(value(n,['filterGroup','filter_group'])||'system').toLowerCase();}
  function notifDot(n){var g=notifGroup(n);return g==='match_fact'?'r':(g==='system'?'a':'g');}
  function notificationRow(n,mobile){var url=value(n,['actionUrl','action_url'])||'#',label=value(n,['actionLabel','action_label'])||'View';var read=!!value(n,['isRead','is_read']);if(mobile)return '<div class="rowline" style="padding:6px 0;border-bottom:1px solid var(--ln);'+(read?'opacity:.6':'')+'"><span class="dotm '+notifDot(n)+'"></span><span class="who"><b>'+esc(value(n,['title'])||'ScoutLink notification')+'</b><span>'+esc(value(n,['body'])||value(n,['typeLabel'])||'')+'</span></span><a class="bt sm '+(notifDot(n)==='r'?'spend':'gh')+'" data-notification-id="'+esc(n.id||'')+'" href="'+esc(clean(url))+'">'+esc(label.replace('Open ','').replace('Record now','Record'))+'</a></div>';return '<div class="kv" style="'+(read?'opacity:.6':'')+'"><span class="flex" style="gap:8px"><span class="dot '+notifDot(n)+'" style="margin-top:4px"></span><span><b style="color:var(--ink)">'+esc(value(n,['title'])||'ScoutLink notification')+'</b><br><span style="font-size:9px">'+esc(value(n,['body'])||value(n,['typeLabel'])||'')+'</span></span></span><b><a class="btn sm '+(notifDot(n)==='r'?'pri':'gh')+'" data-notification-id="'+esc(n.id||'')+'" href="'+esc(clean(url))+'">'+esc(label)+'</a></b></div>';}
  function renderNotifications(){var all=state.notifications||[],filter=state.notifFilter||'all',rows=filter==='all'?all:all.filter(function(n){return notifGroup(n)===filter;});var today=new Date().toDateString(),tod=rows.filter(function(n){var d=new Date(value(n,['createdAt','created_at'])||0);return d.toDateString()===today&&!value(n,['isRead','is_read']);}),earlier=rows.filter(function(n){return tod.indexOf(n)<0;});var filters=[['all','All'],['scout_interest','Scout interest'],['match_fact','Match facts'],['recruitment','Recruitment'],['system','System']];
    desk.innerHTML='<div class="flex" style="gap:6px;margin-bottom:10px">'+filters.map(function(f){var c=f[0]==='all'?all.length:all.filter(function(n){return notifGroup(n)===f[0];}).length;return '<button class="chip '+(filter===f[0]?'on':'')+'" data-notif-filter="'+f[0]+'">'+f[1]+' · '+c+'</button>';}).join('')+'</div><div class="panel rule" style="margin-bottom:12px"><div class="ph3"><b>Today</b></div>'+(tod.length?tod.map(function(n){return notificationRow(n,false);}).join(''):'<div class="mut">Nothing new today.</div>')+'</div><div class="panel rule"><div class="ph3"><b>Earlier this week</b></div>'+(earlier.length?earlier.map(function(n){return notificationRow(n,false);}).join(''):'<div class="mut">No earlier notifications.</div>')+'</div>';
    field.innerHTML=fieldHeader('Inbox',state.unread+' unread · mark all read','<button class="icb" type="button" id="fieldMarkAll">🔔'+(state.unread?'<u>'+state.unread+'</u>':'')+'</button>')+'<div class="stack"><div class="seg"><a href="/coach/chat">Chats</a><a class="on">Notifications</a></div><div class="flex" style="gap:6px">'+filters.slice(0,3).map(function(f){var c=f[0]==='all'?all.length:all.filter(function(n){return notifGroup(n)===f[0];}).length;return '<button class="chip '+(filter===f[0]?'on':'')+'" data-notif-filter="'+f[0]+'">'+f[1]+' · '+c+'</button>';}).join('')+'</div><div class="dateplate">TODAY</div><div class="card rule" style="padding:10px 12px">'+(tod.length?tod.map(function(n){return notificationRow(n,true);}).join(''):'<div class="mut">Nothing new today.</div>')+'</div><div class="dateplate">EARLIER THIS WEEK</div><div class="card rule" style="padding:10px 12px;opacity:.7">'+(earlier.length?earlier.map(function(n){return notificationRow(n,true);}).join(''):'<div class="mut">No earlier notifications.</div>')+'</div></div>';
    bindNotifications();
  }
  function bindNotifications(){document.querySelectorAll('[data-notif-filter]').forEach(function(b){b.onclick=function(){state.notifFilter=b.dataset.notifFilter;renderNotifications();};});document.querySelectorAll('[data-notification-id]').forEach(function(a){a.addEventListener('click',function(){if(a.dataset.notificationId)api('PATCH','/api/notifications/'+encodeURIComponent(a.dataset.notificationId)+'/read',{}).catch(function(){});});});var all=document.getElementById('coachMarkAllRead'),fa=document.getElementById('fieldMarkAll');function mark(){api('PATCH','/api/notifications/mark-all-read',{}).then(loadNotifications).catch(function(e){alert(e.message);});}if(all)all.onclick=mark;if(fa)fa.onclick=mark;}
  async function loadNotifications(){try{var r=await api('GET','/api/notifications?limit=50');state.notifications=list(r,['notifications','data']);state.unread=num(r.unreadCount||r.unread_count,state.notifications.filter(function(n){return !value(n,['isRead','is_read']);}).length);state.notifFilter=state.notifFilter||'all';renderNotifications();if(window.CoachV2)window.CoachV2.refreshBadges();}catch(e){desk.innerHTML=routeMessage('Could not load notifications: '+e.message,true);field.innerHTML=routeMessage('Could not load notifications: '+e.message,true);}}

  /* ================= REPORT A CONCERN ================= */
  function renderConcern(){var email=value(user(),['email','email_address','emailAddr'])||localStorage.getItem('sl_user_email')||'';desk.innerHTML='<div class="panel rule" style="max-width:660px"><div class="ph3"><b>Submit a concern</b></div><form id="concernForm"><div class="field"><label>Category <i>Required</i></label><select name="concernType"><option value="">Select category</option><option>Inappropriate contact</option><option>Suspected misuse</option><option>Incorrect access</option><option>Safeguarding issue</option><option>Another platform-safety concern</option></select></div><div class="mut" style="font-size:9px;margin:-4px 0 8px">Inappropriate contact · Suspected misuse · Incorrect access · Safeguarding issue · Another platform-safety concern</div><div class="field"><label>Who or what does this concern? <i>Optional</i></label><input name="subject" placeholder="—"></div><div class="field"><label>What happened <i>Required</i></label><textarea name="description" placeholder="Describe what you saw, when, and anyone involved. Include message dates if it relates to a conversation."></textarea></div><div class="field"><label>Urgency</label><select name="urgency"><option>Standard review</option><option>Urgent review</option></select></div><input type="hidden" name="contactEmail" value="'+esc(email)+'"><input type="hidden" name="contactName" value="'+esc(fullName())+'"><div id="concernMsg"></div><div class="flex" style="justify-content:flex-end"><button class="btn pri" type="submit">Submit concern</button></div><div class="mut" style="font-size:9px;margin-top:8px">Submissions are encrypted and visible only to the trust team. If someone is in immediate danger, contact emergency services first.</div></form></div>';
    field.innerHTML=fieldHeader('Report a Concern','Reviewed by the Stratex trust team','<span class="avm">'+esc(initials(fullName()))+'</span>')+'<div class="card rule"><form id="fieldConcernForm"><div class="field"><label>Category <i>Required</i></label><select name="concernType"><option value="">Select category</option><option>Inappropriate contact</option><option>Suspected misuse</option><option>Incorrect access</option><option>Safeguarding issue</option><option>Another platform-safety concern</option></select></div><div class="field"><label>Who or what? <i>Optional</i></label><input name="subject"></div><div class="field"><label>What happened <i>Required</i></label><textarea name="description"></textarea></div><div class="field"><label>Urgency</label><select name="urgency"><option>Standard review</option><option>Urgent review</option></select></div><input type="hidden" name="contactEmail" value="'+esc(email)+'"><input type="hidden" name="contactName" value="'+esc(fullName())+'"><div id="fieldConcernMsg"></div><button class="bt pri blk" type="submit">Submit concern</button></form></div>';
    ['concernForm','fieldConcernForm'].forEach(function(id){var f=document.getElementById(id);if(f)f.onsubmit=submitConcern;});
  }
  function submitConcern(e){e.preventDefault();var form=e.currentTarget,fd=new FormData(form),body={sourcePage:'/coach/report-a-concern'};fd.forEach(function(v,k){body[k]=v;});var msg=form.querySelector('#concernMsg,#fieldConcernMsg');if(!body.concernType||!String(body.description||'').trim()||!body.contactEmail){msg.innerHTML=routeMessage('Complete category and description. Your signed-in email is also required.',true);return;}var btn=form.querySelector('button[type="submit"]');btn.disabled=true;fetch((window.API||'')+'/api/trust/safeguarding-concerns',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(function(r){return r.json().then(function(d){if(!r.ok)throw new Error(d.error||'Could not submit concern');return d;});}).then(function(d){msg.innerHTML=routeMessage(d.message||('Concern submitted'+(d.reference?' — reference '+d.reference:'')+'.'));form.reset();window.CoachV2.showToast('Concern submitted.');}).catch(function(err){msg.innerHTML=routeMessage(err.message,true);}).finally(function(){btn.disabled=false;});}

  /* ================= SETTINGS ================= */
  function renderSettings(){var p=state.settingsProfile||{},coaches=state.settingsCoaches||[];desk.innerHTML='<div style="display:grid;grid-template-columns:190px minmax(0,1fr);gap:12px;align-items:start"><div class="panel rule" style="padding:8px 0" id="settingsRail">'+[['team','Team Coaches'],['profile','Profile'],['notifications','Notification Preferences'],['privacy','Privacy & visibility'],['password','Change Password'],['appearance','Appearance'],['danger','Danger Zone']].map(function(x,i){return '<button class="kv" style="width:100%;padding:6px 14px;border-left:0;border-right:0;border-top:0;background:'+(i===0?'var(--turf-t)':'transparent')+';text-align:left" data-settings-pane="'+x[0]+'"><span style="'+(x[0]==='danger'?'color:var(--rd)':'')+'">'+x[1]+'</span><b></b></button>';}).join('')+'</div><div id="settingsPane"><div class="panel rule" style="margin-bottom:12px"><div class="ph3"><b>Team Coaches</b><span class="m">'+(p.is_super_user?'Super user':'Coach')+'</span><span class="r"><button class="btn sm" id="inviteCoach">Invite Coach</button></span></div>'+coaches.map(function(c){return '<div class="kv"><span class="pw"><span class="av">'+esc(initials([c.first_name,c.last_name].filter(Boolean).join(' ')))+'</span><span class="who"><b>'+esc([c.first_name,c.last_name].filter(Boolean).join(' ')||'Coach')+'</b><span>'+(c.is_super_user?'Head coach · owner':'Assistant coach · assigned players')+(String(c.id)===String(p.id)?' · You':'')+'</span></span></span><b></b></div>';}).join('')+'</div><div class="panel rule" style="margin-bottom:12px"><div class="ph3"><b>Notification Preferences</b></div>'+[['scout','Scout interest','Messages and profile views from reviewed scouts'],['match','Match Facts reminders','Nudge when a completed fixture has nothing recorded'],['system','System updates','Product and account notices']].map(function(x,i){return '<div class="kv"><span><b style="color:var(--ink)">'+x[1]+'</b><br><span style="font-size:9px">'+x[2]+'</span></span><b><button class="chip '+(i<2?'on':'')+'" data-pref="'+x[0]+'">'+(i<2?'On':'Off')+'</button></b></div>';}).join('')+'</div><div class="panel rule" style="margin-bottom:12px"><div class="ph3"><b>Appearance</b></div><div class="kv"><span>Theme</span><b class="flex" style="gap:6px"><button class="chip on" data-theme="light">Light</button><button class="chip" data-theme="dark">Dark</button></b></div></div><div class="panel rule" style="margin-bottom:12px"><div class="ph3"><b>Change Password</b></div><div class="two"><div class="field"><label>New password</label><input id="newPassword" type="password" placeholder="Minimum 8 characters"></div><div class="field"><label>Confirm password</label><input id="confirmPassword" type="password"></div></div><button class="btn pri" id="changePassword">Update Password</button></div><div class="panel rule" style="border-top-color:var(--rd)"><div class="ph3"><b>Danger Zone</b></div><div class="kv"><span><b style="color:var(--ink)">Deactivate Account</b><br><span style="font-size:9px">Player records remain with the team under safeguarding retention rules; your access ends. Requires typing the team name.</span></span><b><button class="btn sm" style="border-color:var(--rd);color:var(--rd)" id="deactivateCoach">Deactivate Account</button></b></div></div></div></div>';
    field.innerHTML=fieldHeader('More',team()+(age()?' · '+age():'')+' · '+fullName(),'<span class="avm">'+esc(initials(fullName()))+'</span>')+'<div class="stack"><div class="card rule" style="padding:10px 12px"><a class="rowline" href="/coach/video-reels" style="padding:7px 0;border-bottom:1px solid var(--ln);text-decoration:none"><span class="who"><b>Video Reels</b><span>Review clips and upload links</span></span><span>›</span></a><a class="rowline" href="/coach/fixtures" style="padding:7px 0;border-bottom:1px solid var(--ln);text-decoration:none"><span class="who"><b>Fixtures</b><span>Agenda and Match Facts status</span></span><span>›</span></a><a class="rowline" href="/coach/add-player" style="padding:7px 0;text-decoration:none"><span class="who"><b>Add Player</b><span>the four-stage wizard</span></span><span>›</span></a></div><div class="card rule" style="padding:10px 12px"><div class="rowline" style="padding:7px 0;border-bottom:1px solid var(--ln)"><span class="who"><b>Team & coaches</b><span>'+coaches.length+' active coach'+(coaches.length===1?'':'es')+'</span></span><span>›</span></div><div class="rowline" style="padding:7px 0;border-bottom:1px solid var(--ln)"><span class="who"><b>Notification preferences</b><span>scout interest · MF reminders · system</span></span><span>›</span></div><div class="rowline" style="padding:7px 0"><span class="who"><b>Appearance</b><span>Light</span></span><span>›</span></div></div><a class="card" href="/coach/report-a-concern" style="border-color:var(--rd);text-decoration:none"><div class="rowline"><span class="who"><b style="color:var(--rd)">Report a Concern</b><span>reviewed by the Stratex trust team</span></span><span>›</span></div></a><div class="callout"><b>On Coach Desk:</b> Bulk Import · CSV fixtures · full My Players table · coach invites · Change Password · the Danger Zone. Field links out rather than miniaturising them.</div><button class="bt gh blk" data-coach-signout>Sign out</button></div>';
    bindSettings();
  }
  function bindSettings(){var invite=document.getElementById('inviteCoach');if(invite)invite.onclick=function(){window.CoachV2.openDrawer({title:'Invite Coach',html:'<form id="inviteCoachForm"><div class="two"><div class="field"><label>First name</label><input name="firstName"></div><div class="field"><label>Last name</label><input name="lastName"></div></div><div class="field"><label>Email</label><input name="emailAddr" type="email"></div><div class="field"><label>Phone</label><input name="phone"></div><label class="chip"><input name="isSuperUser" type="checkbox"> Super user</label><div id="inviteMsg"></div><div class="flex" style="justify-content:flex-end;margin-top:10px"><button class="btn pri" type="submit">Invite Coach</button></div></form>'});setTimeout(function(){var f=document.getElementById('inviteCoachForm');if(f)f.onsubmit=function(e){e.preventDefault();var fd=new FormData(f),body={firstName:fd.get('firstName'),lastName:fd.get('lastName'),emailAddr:fd.get('emailAddr'),phone:fd.get('phone')||null,isSuperUser:fd.get('isSuperUser')==='on'};api('POST','/api/coaches/add-coach',body).then(function(){window.CoachV2.closeAll();window.CoachV2.showToast('Coach invited.');loadSettings();}).catch(function(err){document.getElementById('inviteMsg').innerHTML=routeMessage(err.message,true);});};},0);};document.querySelectorAll('[data-pref]').forEach(function(b){b.onclick=function(){b.classList.toggle('on');b.textContent=b.classList.contains('on')?'On':'Off';};});document.querySelectorAll('[data-theme]').forEach(function(b){b.onclick=function(){document.querySelectorAll('[data-theme]').forEach(function(x){x.classList.toggle('on',x===b);});if(typeof window.applyTheme==='function')window.applyTheme(b.dataset.theme);try{localStorage.setItem('sl_theme',b.dataset.theme);}catch(_){};};});var cp=document.getElementById('changePassword');if(cp)cp.onclick=function(){var np=document.getElementById('newPassword').value,cf=document.getElementById('confirmPassword').value;if(np.length<8)return alert('Password must be at least 8 characters.');if(np!==cf)return alert('Passwords do not match.');api('POST','/api/auth/change-password',{password:np}).then(function(){window.CoachV2.showToast('Password updated.');document.getElementById('newPassword').value='';document.getElementById('confirmPassword').value='';}).catch(function(e){alert(e.message);});};var de=document.getElementById('deactivateCoach');if(de)de.onclick=function(){var expected=team();window.CoachV2.openModal({title:'Deactivate account',html:'<div style="font-size:10.5px;margin-bottom:8px">This ends your access to <b>'+esc(expected)+'</b>. Player records are retained under safeguarding rules. Type the team name to confirm.</div><div class="field"><label>Team name</label><input id="deactivateTeamName"></div><div class="callout a">The current backend has no verified destructive deactivation endpoint. This confirmation is deliberately non-destructive until that server action exists.</div>',footer:'<button class="btn gh" data-close-coach-overlay>Cancel</button><button class="btn" style="border-color:var(--rd);color:var(--rd)" id="confirmDeactivate" disabled>Deactivate</button>'});setTimeout(function(){var inp=document.getElementById('deactivateTeamName'),btn=document.getElementById('confirmDeactivate');if(inp&&btn)inp.oninput=function(){btn.disabled=inp.value.trim()!==expected;};if(btn)btn.onclick=function(){window.CoachV2.showToast('Deactivation is not enabled server-side.');window.CoachV2.closeAll();};},0);};var save=document.getElementById('coachSavePreferences');if(save)save.onclick=function(){window.CoachV2.showToast('Preferences saved on this device.');};}
  async function loadSettings(){try{var pr=await api('GET','/api/coaches/profile');state.settingsProfile=pr.coach||pr.profile||pr;var cr=await api('GET','/api/coaches/team-coaches').catch(function(){return{data:[]};});state.settingsCoaches=[state.settingsProfile].concat(list(cr,['coaches','data'])).filter(function(c,i,a){return c&&c.id&&a.findIndex(function(x){return x&&String(x.id)===String(c.id);})===i;});renderSettings();}catch(e){desk.innerHTML=routeMessage(e.message,true);field.innerHTML=routeMessage(e.message,true);}}

  function boot(){
    if(window.CoachV2&&!window.CoachV2.allowedCoach()&&page!=='report-a-concern'){location.href='/login';return;}
    if(page==='dashboard')initDashboard();
    else if(page==='my-players')initPlayers();
    else if(page==='fixtures')loadFixtures();
    else if(page==='video-reels')loadVideos();
    else if(page==='chat')initChat();
    else if(page==='notifications')loadNotifications();
    else if(page==='report-a-concern')renderConcern();
    else if(page==='settings')loadSettings();
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
}());
